type Shape = "circle" | "square";

function area(shape: Shape, size: number): number {
    if (shape === "circle") return Math.PI * size ** 2;
    return size ** 2;
}

public static int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}

